/* TOKEN_RADAR: dark terminal theme. Palette: void, panel, line, phosphor, amber, dim, red. */
:root {
  --void: #070c10;
  --panel: #0c141a;
  --panel-2: #101b23;
  --line: #1d2f3a;
  --line-soft: #14232c;
  --ink: #d9f2e4;
  --dim: #7ea08f;
  --faint: #4d6a5c;
  --phos: #3dff9e;
  --phos-dim: #1fae6b;
  --amber: #ffbf3d;
  --red: #ff5d5d;
  --mono: ui-monospace, "SF Mono", "Cascadia Code", Menlo, Consolas, monospace;
  --sans: ui-monospace, "SF Mono", "Cascadia Code", Menlo, Consolas, monospace;
  --r: 10px;
}
* { box-sizing: border-box; }
html { color-scheme: dark; scrollbar-color: var(--phos-dim) var(--void); }
body {
  margin: 0;
  background: var(--void);
  background-image:
    radial-gradient(1100px 320px at 15% -80px, rgba(61, 255, 158, 0.09), transparent 60%),
    radial-gradient(900px 300px at 95% -60px, rgba(255, 191, 61, 0.06), transparent 60%),
    repeating-linear-gradient(0deg, rgba(61, 255, 158, 0.022) 0 1px, transparent 1px 3px);
  color: var(--ink);
  font-family: var(--sans);
  font-size: 14px;
  line-height: 1.55;
  min-height: 100vh;
}
::selection { background: var(--phos); color: #04110a; }
h1, h2, h3 { margin: 0; letter-spacing: 0; }
h1 { font-size: 26px; line-height: 1.2; font-weight: 700; }
h2 { font-size: 16px; font-weight: 700; }
h3 { font-size: 13px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.08em; color: var(--dim); }
p { margin: 0; }
button, input, select { font: inherit; color: inherit; }
button { cursor: pointer; }
a { color: var(--phos); }
:focus-visible { outline: 2px solid var(--phos); outline-offset: 2px; }
.skip { position: absolute; left: -999px; top: 8px; background: var(--phos); color: #04110a; padding: 8px 14px; border-radius: 6px; z-index: 50; }
.skip:focus { left: 8px; }

.shell { max-width: 1240px; margin: 0 auto; padding: 20px 22px 56px; }
.topbar {
  display: flex; align-items: center; justify-content: space-between; gap: 12px; flex-wrap: wrap;
  border: 1px solid var(--line); border-radius: var(--r); background: var(--panel);
  padding: 10px 14px;
}
.brand { display: flex; align-items: center; gap: 10px; font-weight: 700; font-size: 14px; letter-spacing: 0.06em; }
.prompt { color: var(--phos); }
.cursor { display: inline-block; width: 9px; height: 16px; background: var(--phos); vertical-align: -3px; animation: blink 1.1s steps(1) infinite; }
@keyframes blink { 50% { opacity: 0; } }
.meta { display: flex; gap: 8px; flex-wrap: wrap; }
.chip {
  border: 1px solid var(--line); border-radius: 999px; padding: 3px 10px;
  font-size: 12px; color: var(--dim); background: var(--panel-2); white-space: nowrap;
}
.chip b { color: var(--phos); font-weight: 700; }

.hero { display: grid; grid-template-columns: minmax(0, 1.5fr) minmax(280px, 0.7fr); gap: 18px; padding: 26px 2px 18px; }
.hero h1 .glow { color: var(--phos); text-shadow: 0 0 18px rgba(61, 255, 158, 0.45); }
.lede { color: var(--dim); margin-top: 10px; max-width: 68ch; font-size: 13.5px; }
.lede b { color: var(--ink); }
.stats { display: grid; grid-template-columns: 1fr 1fr; gap: 1px; background: var(--line-soft); border: 1px solid var(--line-soft); border-radius: var(--r); overflow: hidden; align-self: start; }
.stat { background: var(--panel); padding: 12px 14px; }
.stat span { display: block; font-size: 11px; text-transform: uppercase; letter-spacing: 0.08em; color: var(--faint); }
.stat b { font-size: 20px; color: var(--phos); font-weight: 700; font-variant-numeric: tabular-nums; }
.stat b.amber { color: var(--amber); }

.toolbar {
  display: flex; flex-wrap: wrap; gap: 10px; align-items: end;
  border: 1px solid var(--line); border-radius: var(--r); background: var(--panel);
  padding: 12px 14px; margin-bottom: 12px;
}
.field { display: grid; gap: 6px; }
.field label { font-size: 11px; text-transform: uppercase; letter-spacing: 0.08em; color: var(--faint); }
.field input, .field select {
  background: var(--void); border: 1px solid var(--line); border-radius: 7px;
  padding: 8px 10px; min-height: 36px; color: var(--ink);
}
.field input { min-width: min(300px, 60vw); }
.field input::placeholder { color: var(--faint); }
.field input:focus, .field select:focus { border-color: var(--phos); outline: none; }
.tabs { display: flex; gap: 4px; border: 1px solid var(--line); border-radius: 8px; padding: 3px; background: var(--void); }
.tabs button { border: 0; border-radius: 6px; background: transparent; color: var(--dim); padding: 7px 14px; font-size: 13px; }
.tabs button[aria-pressed="true"] { background: var(--phos); color: #04110a; font-weight: 700; }
.count { margin-left: auto; color: var(--faint); font-size: 12px; align-self: center; }
.count b { color: var(--phos); }

.panel { background: var(--panel); border: 1px solid var(--line); border-radius: var(--r); overflow: hidden; }
.table-wrap { overflow-x: auto; }
table { width: 100%; border-collapse: collapse; font-size: 13px; min-width: 760px; }
caption { text-align: left; padding: 10px 14px; color: var(--faint); font-size: 12px; border-bottom: 1px solid var(--line-soft); }
th, td { padding: 10px 12px; border-bottom: 1px solid var(--line-soft); text-align: left; vertical-align: middle; }
th { font-size: 11px; text-transform: uppercase; letter-spacing: 0.07em; color: var(--faint); font-weight: 700; white-space: nowrap; }
th button { display: inline-flex; align-items: center; gap: 6px; border: 0; background: none; padding: 0; color: inherit; font: inherit; text-transform: inherit; letter-spacing: inherit; }
th button:hover { color: var(--phos); }
tbody tr { cursor: pointer; }
tbody tr:hover { background: rgba(61, 255, 158, 0.05); }
tbody tr[data-selected="true"] { background: rgba(61, 255, 158, 0.09); box-shadow: inset 2px 0 0 var(--phos); }
.num { font-variant-numeric: tabular-nums; white-space: nowrap; }
.rankcell { color: var(--phos); font-weight: 700; }
.name b { font-weight: 700; }
.sub { color: var(--faint); font-size: 12px; }
.pos { color: var(--phos); }
.neg { color: var(--red); }
.bar { width: 110px; height: 6px; border-radius: 3px; background: var(--line-soft); overflow: hidden; flex: none; }
.bar i { display: block; height: 100%; background: linear-gradient(90deg, var(--phos-dim), var(--phos)); }
.implied { display: flex; align-items: center; gap: 10px; }
.pill {
  display: inline-flex; align-items: center; gap: 6px; font-size: 11px; white-space: nowrap;
  border: 1px solid var(--line); border-radius: 999px; padding: 2px 9px; color: var(--dim); background: var(--panel-2);
}
.pill::before { content: ""; width: 6px; height: 6px; border-radius: 50%; background: var(--phos); box-shadow: 0 0 8px var(--phos); }
.pill.live::before { background: var(--amber); box-shadow: 0 0 8px var(--amber); }
.tag { border: 1px solid var(--line); border-radius: 5px; padding: 1px 7px; font-size: 11px; color: var(--amber); background: rgba(255, 191, 61, 0.07); white-space: nowrap; }

.explainer { margin-top: 12px; padding: 18px; display: grid; gap: 12px; }
.explainer-head { display: flex; align-items: baseline; justify-content: space-between; gap: 10px; flex-wrap: wrap; }
.formula {
  border: 1px dashed var(--phos-dim); border-radius: 8px; background: rgba(61, 255, 158, 0.04);
  padding: 12px 14px; font-size: 12.5px; line-height: 1.8; overflow-wrap: anywhere; color: var(--ink);
}
.formula b { color: var(--phos); }
.comps { display: flex; flex-wrap: wrap; gap: 6px; }
.comp { border: 1px solid var(--line); border-radius: 6px; padding: 3px 9px; font-size: 12px; color: var(--dim); background: var(--void); }
.comp b { color: var(--amber); }
.explainer p.note { color: var(--faint); font-size: 12.5px; }

.empty { padding: 48px 20px; text-align: center; display: grid; gap: 10px; justify-items: center; }
.empty p { color: var(--dim); }
.button { min-height: 36px; padding: 0 16px; border: 1px solid var(--line); border-radius: 7px; background: var(--panel-2); color: var(--ink); }
.button.primary { background: var(--phos); border-color: var(--phos); color: #04110a; font-weight: 700; }

.detail { background: var(--panel); color: var(--ink); border: 1px solid var(--phos-dim); border-radius: 12px; padding: 0; width: min(680px, calc(100vw - 32px)); max-height: min(88vh, 900px); }
.detail::backdrop { background: rgba(2, 6, 8, 0.72); backdrop-filter: blur(2px); }
.detail-inner { padding: 20px 22px 24px; overflow: auto; max-height: min(88vh, 900px); }
.detail-head { display: flex; align-items: start; justify-content: space-between; gap: 14px; }
.detail-head h2 { margin-top: 6px; font-size: 21px; }
.close { flex: none; min-height: 32px; padding: 4px 14px; border: 1px solid var(--line); border-radius: 7px; background: var(--void); }
.close:hover { border-color: var(--phos); color: var(--phos); }
.kv { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; margin-top: 14px; }
.kv div { border: 1px solid var(--line-soft); border-radius: 8px; padding: 8px 10px; background: var(--void); }
.kv span { display: block; font-size: 10.5px; text-transform: uppercase; letter-spacing: 0.07em; color: var(--faint); }
.kv b { font-variant-numeric: tabular-nums; }
.detail-section { margin-top: 18px; padding-top: 16px; border-top: 1px solid var(--line-soft); }
.detail-section h3 { margin-bottom: 10px; }
.equation { display: grid; gap: 6px; font-size: 13px; }
.equation div { display: flex; justify-content: space-between; gap: 12px; border-bottom: 1px dotted var(--line); padding-bottom: 5px; }
.equation span { color: var(--dim); }
.equation b { font-variant-numeric: tabular-nums; }
.equation .total { border-bottom: 0; }
.equation .total b { color: var(--phos); font-size: 15px; }
.math { color: var(--faint); font-size: 12px; margin-top: 8px; overflow-wrap: anywhere; }
.steps { margin: 10px 0 0; padding: 0; list-style: none; display: grid; gap: 10px; counter-reset: step; }
.steps li { counter-increment: step; border: 1px solid var(--line-soft); border-radius: 8px; padding: 10px 12px 10px 44px; position: relative; background: var(--void); }
.steps li::before {
  content: counter(step, decimal-leading-zero); position: absolute; left: 12px; top: 11px;
  color: var(--phos); font-weight: 700; font-size: 12px;
}
.steps b { display: block; font-weight: 600; font-size: 13px; }
.cost { color: var(--amber); font-size: 12px; }
.warn { border: 1px solid rgba(255, 93, 93, 0.4); background: rgba(255, 93, 93, 0.07); color: #ffb3b3; border-radius: 8px; padding: 10px 12px; font-size: 12.5px; margin-top: 12px; }
.footer { padding: 18px 2px 0; color: var(--faint); font-size: 12px; display: flex; justify-content: space-between; gap: 10px; flex-wrap: wrap; }

@media (max-width: 900px) {
  .hero { grid-template-columns: 1fr; }
  .stats { grid-template-columns: 1fr 1fr; }
  .kv { grid-template-columns: 1fr 1fr; }
}
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition-duration: 0.01ms !important; animation-duration: 0.01ms !important; }
  .cursor { animation: none; }
}
